// Retrieve the array of files from the first incoming item
const files = $input.first().json.files || [];

// Map and split them into individual n8n items
return files.map(data => {
  return { 
    json: { 
      id: data.id, 
      name: data.name 
    } 
  };
});

// 1. Lock in the text directly from the extraction node
const text = $node["Extract from File"]?.json?.text || '';

// 2. Safely grab the DB info (with fallbacks for testing)
let dbFileName;
let googleFileId = "Unknown ID";
try {
    dbFileName = $node["Check Current Doc Status"].json.file_name;
    googleFileId = $node["Check Current Doc Status"].json.google_file_id;
} catch (error) {
    // If the database node hasn't run during testing, safely ignore it
}

const pdfTitle = $node["Extract from File"]?.json?.info?.Title;
const fileName = pdfTitle || dbFileName || "Unknown File";

// 3. Safely check the loop node without crashing on the first run
let loopPage;
try {
  loopPage = $node["Loop Back to First Doc"].json.current_page;
} catch (error) {
  loopPage = null; // If it hasn't run yet, ignore the error
}

// ALWAYS prioritize the Loop Node's page number so it actually advances!
const currentPage = parseInt(loopPage || $input.item.json.current_page || 1);

// 4. Math for the chunks
const charsPerPage = 3000;
const startChar = (currentPage - 1) * charsPerPage;
let endChar = currentPage * charsPerPage;
let isEof = false;

// 5. Calculate total pages
const totalPages = Math.ceil(text.length / charsPerPage);

if (startChar >= text.length) isEof = true;
if (endChar >= text.length) { endChar = text.length; isEof = true; }

// 6. Send it forward!
return {
  text_chunk: text.substring(startChar, endChar),
  current_page: currentPage,
  total_pages: totalPages, 
  next_page: isEof ? currentPage : currentPage + 1,
  is_eof: isEof,
  file_name: fileName,
  google_file_id: googleFileId
};

const responseText = $input.item.json.response || '';
let items = [];

try {
  const parsed = JSON.parse(responseText);
  // This line now forces it into an array, even if the AI returned a single object
  items = Array.isArray(parsed.questions) ? parsed.questions : (parsed.questions ? [parsed.questions] : (Array.isArray(parsed) ? parsed : [parsed]));
} catch (e) {
  console.error("JSON Parse Error:", e);
}

if (!items || items.length === 0) {
  return [{
    Date: new Date().toISOString().split('T')[0],
    Question: "⚠️ MANUAL REVIEW REQUIRED: Malformed output.",
    User_Answer: "N/A",
    Status: "Review Needed",
    Source_Doc: $node["Resilient Slice"].json.file_name,
    Source_Page: `Page ${$node["Resilient Slice"].json.current_page} of ${$node["Resilient Slice"].json.total_pages}`
  }];
}

return items.map(q => ({
  Date: new Date().toISOString().split('T')[0],
  Question: q.question_text || q.question || "Invalid Question Format",
  Ideal_Answer: q.ideal_answer,
  User_Answer: "",
  Status: "Pending",
  Source_Doc: $node["Resilient Slice"].json.file_name,
  Source_Page: `Page ${$node["Resilient Slice"].json.current_page} of ${$node["Resilient Slice"].json.total_pages}`
}));

